import json,sys
try:
    c=json.load(open('config.json',encoding='utf-8-sig'))
except Exception:
    print('load-fail');sys.exit(0)
def merge(a,b):
    r=dict(a)
    for k,v in b.items():
        r[k]=merge(r[k],v) if isinstance(v,dict) and isinstance(r.get(k),dict) else v
    return r
def flat(d,p=''):
    o=[]
    for k,v in d.items():
        if isinstance(v,dict): o+=flat(v,p+k+'.')
        else: o.append((p+k,v))
    return o
J=lambda v:json.dumps(v,ensure_ascii=False)
ok=sorted(c)==['defaults','environments','version'] and c['version']==1 and sorted(c['environments'])==['dev','prod','test'] and all(sorted(e)==['overrides'] for e in c['environments'].values())
print('structure',ok)
if not ok: sys.exit(0)
d=c['defaults']
dv={k:J(v) for k,v in flat(d)}
print('dev-overrides-empty',c['environments']['dev']['overrides']=={})
red=0
for n,e in c['environments'].items():
    for k,v in flat(e['overrides']):
        if k not in dv or dv[k]==J(v): red+=1
print('redundant',red)
for n in ('dev','test','prod'):
    for k,v in sorted(flat(merge(d,c['environments'][n]['overrides']))):
        print(n,k+'='+J(v))
